import { expect, expectStatus, test, uniqueName, type APIRequestContext } from "../../fixtures";

interface DocumentOut {
  id: string;
  vendor_id: string;
  kind: string;
  status: string;
}

interface ExtractionOut {
  id: string;
  document_id: string;
  kind: string;
  status: string;
  fields: Record<string, { value: string | null; confidence: number }>;
}

test.describe("LIF-08 vendor lifecycle", () => {
  test(
    "a certificate whose expiry date could not be read cannot be approved",
    { tag: "@LIF-08" },
    async ({ apiAs }) => {
      // Arrange: a member creates a uniquely named vendor and submits an insurance certificate.
      const member: APIRequestContext = await apiAs("member");
      const reviewer: APIRequestContext = await apiAs("reviewer");
      const vendorName = uniqueName("LIF-08 Vendor");

      const vendor = await expectStatus<{ id: string }>(
        await member.post("/api/vendors", {
          data: {
            name: vendorName,
            category: "services",
            contact_email: `${vendorName.toLowerCase().replace(/[^a-z0-9]/g, "")}@vendors.test`,
          },
        }),
        201,
      );

      // The certificate is uploaded with an expiry the extractor cannot parse ("next spring").
      const document = await expectStatus<DocumentOut>(
        await member.post(`/api/vendors/${vendor.id}/documents`, {
          multipart: {
            kind: "insurance_certificate",
            file: {
              name: "certificate.pdf",
              mimeType: "application/pdf",
              buffer: Buffer.from("Certificate of insurance. Expires: next spring"),
            },
          },
        }),
        201,
      );

      await expectStatus(await member.post(`/api/vendors/${vendor.id}/submit`), 200);

      // Wait for extraction to finish for the uploaded document.
      await expect
        .poll(
          async () =>
            (await expectStatus<DocumentOut>(await member.get(`/api/documents/${document.id}`), 200)).status,
          { timeout: 60_000 },
        )
        .toBe("extracted");

      const extraction = await expectStatus<ExtractionOut>(
        await reviewer.get(`/api/documents/${document.id}/extraction`),
        200,
      );
      expect(extraction.status).toBe("pending_review");
      expect(extraction.kind).toBe("insurance_certificate");

      // Act: the reviewer tries to approve the extraction.
      const response = await reviewer.post(`/api/extractions/${extraction.id}/decision`, {
        data: { decision: "approve" },
      });

      // Assert: approval is refused with the scenario's error code.
      const body = await expectStatus<{ error: { code: string } }>(response, 409);
      expect(body.error.code).toBe("insurance_expiry_missing");

      // The extraction remains pending review.
      const after = await expectStatus<ExtractionOut>(
        await reviewer.get(`/api/documents/${document.id}/extraction`),
        200,
      );
      expect(after.status).toBe("pending_review");
      expect(after.id).toBe(extraction.id);
    },
  );
});
